package vn.edu.eaut.lab7.model;
public class SinhVien { private int id; private String ma,hoTen,email,soDienThoai; public SinhVien(){} public SinhVien(int id,String ma,String hoTen,String email,String soDienThoai){this.id=id;this.ma=ma;this.hoTen=hoTen;this.email=email;this.soDienThoai=soDienThoai;} public int getId(){return id;} public void setId(int v){id=v;} public String getMa(){return ma;} public void setMa(String v){ma=v;} public String getHoTen(){return hoTen;} public void setHoTen(String v){hoTen=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getSoDienThoai(){return soDienThoai;} public void setSoDienThoai(String v){soDienThoai=v;} }